package com.example.smartexpenseanalyzer.controller;
import com.example.smartexpenseanalyzer.service.ApiFacade; import jakarta.servlet.http.HttpSession; import org.springframework.http.ResponseEntity; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/auth") public class RegistrationController { private final ApiFacade app; public RegistrationController(ApiFacade app){this.app=app;} @PostMapping("/register") public ResponseEntity<?> register(@RequestBody Map<String,String> body,HttpSession session){return app.register(body,session);} @PostMapping("/login") public ResponseEntity<?> login(@RequestBody Map<String,String> body,HttpSession session){return app.login(body,session);} @PostMapping("/logout") public Map<String,String> logout(HttpSession session){return app.logout(session);} @GetMapping("/me") public Map<String,Object> me(HttpSession session){return app.current(session);} }
